<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://newhampshireinsuranceappraiser.com/#business","name":"New Hampshire Insurance Appraiser","url":"https://newhampshireinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@newhampshireinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://newhampshireinsuranceappraiser.com/#logo","url":"https://newhampshireinsuranceappraiser.com/favicon-512.png","contentUrl":"https://newhampshireinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"New Hampshire Insurance Appraiser"},"image":{"@id":"https://newhampshireinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"NH","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@newhampshireinsuranceappraiser.com","contactType":"customer service","areaServed":"US-NH","availableLanguage":"en"}],"slogan":"Independent appraisal for property claims that came up short","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across New Hampshire.","areaServed":[{"@type":"State","name":"New Hampshire"},{"@type":"City","name":"Manchester"},{"@type":"City","name":"Nashua"},{"@type":"City","name":"Concord"},{"@type":"City","name":"Portsmouth"},{"@type":"City","name":"Dover"},{"@type":"City","name":"Rochester"},{"@type":"City","name":"Derry"},{"@type":"City","name":"Salem"},{"@type":"City","name":"Keene"},{"@type":"City","name":"Laconia"},{"@type":"City","name":"Lebanon"},{"@type":"City","name":"Hanover"},{"@type":"City","name":"North Conway"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Policyholder’s Appraiser on the Panel","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/appraisal-clause-representation-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Single-Family Home Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/homeowners-claim-appraisal-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Condo, Association & Business Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/nh-commercial-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof Damage & Hail Disputes","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/roof-and-hail-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Microburst & Windstorm Losses","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/wind-microburst-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tropical Remnants & Coastal Storms","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/tropical-storm-hurricane-appraisal-nh/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Frozen Pipe & Leak Claims","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/pipe-burst-water-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Chimney, Fire & Smoke Losses","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/fire-smoke-soot-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dams & Heavy Roof Snow","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/ice-dam-roof-snow-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Trees Down on the Property","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/falling-tree-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Line-by-Line Estimate Audit","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/insurer-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Appointments","url":"https://newhampshireinsuranceappraiser.com/nh-appraisal-services/appraisal-umpire-nh/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Roof snow load","Umpire services"],"priceRange":"$$","openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://newhampshireinsuranceappraiser.com/#website","url":"https://newhampshireinsuranceappraiser.com/","name":"New Hampshire Insurance Appraiser","publisher":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#webpage","url":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/","name":"Insurance Claim Glossary | NH Appraisal Terms","description":"Insurance claim glossary for NH owners: plain-English definitions of ACV, RCV, umpire, ice dam, proof of loss, O&P and dozens more terms.","inLanguage":"en-US","isPartOf":{"@id":"https://newhampshireinsuranceappraiser.com/#website"},"about":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"publisher":{"@id":"https://newhampshireinsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#primaryimage","url":"https://newhampshireinsuranceappraiser.com/assets/img/photos/calculator-papers.webp","width":1024,"height":682},"breadcrumb":{"@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#breadcrumb"},"mainEntity":{"@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#definedtermset"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://newhampshireinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Claim glossary","item":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/"}],"@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#breadcrumb"},{"@type":"DefinedTermSet","name":"New Hampshire property insurance claim glossary","hasDefinedTerm":[{"@type":"DefinedTerm","name":"Actual Cash Value (ACV)","description":"Replacement cost minus depreciation. Many policies pay ACV first and the balance once repairs are finished."},{"@type":"DefinedTerm","name":"Additional Living Expense (ALE)","description":"The extra cost of living elsewhere while your home can’t be lived in after a covered loss, usually paid under Coverage D."},{"@type":"DefinedTerm","name":"Amount of Loss","description":"The dollar value of the damage from a covered loss. It is the question an appraisal panel is set up to answer."},{"@type":"DefinedTerm","name":"Appraisal Award","description":"The written figure that settles the amount of loss, signed by any two of the three panel members."},{"@type":"DefinedTerm","name":"Appraisal Clause","description":"The policy provision that lets either side demand appraisal when they disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Appraisal Demand","description":"The written notice that starts appraisal, identifying the claim and stating that the parties disagree on the amount of loss."},{"@type":"DefinedTerm","name":"Competent and Disinterested","description":"Common policy wording for an appraiser: someone qualified to value the loss and without a personal stake in the outcome."},{"@type":"DefinedTerm","name":"Coverage A (Dwelling)","description":"Coverage for the house itself and structures attached to it, such as an attached garage or deck."},{"@type":"DefinedTerm","name":"Coverage B (Other Structures)","description":"Coverage for detached buildings and structures, such as a barn, shed, fence or detached garage."},{"@type":"DefinedTerm","name":"Coverage C (Personal Property)","description":"Coverage for belongings and contents, often subject to special limits for items like jewelry or firearms."},{"@type":"DefinedTerm","name":"Coverage D (Loss of Use)","description":"Coverage for additional living expense or lost rent while the property is unusable after a covered loss."},{"@type":"DefinedTerm","name":"Declarations Page","description":"The summary page of a policy showing the insured property, coverages, limits, deductibles and policy period."},{"@type":"DefinedTerm","name":"Deductible","description":"The portion of a covered loss you absorb before the insurer pays, either a flat amount or a percentage."},{"@type":"DefinedTerm","name":"Depreciation","description":"A reduction in value for age, wear and condition, subtracted from replacement cost to reach actual cash value."},{"@type":"DefinedTerm","name":"Detach and Reset","description":"Removing an undamaged item to repair something else, then reinstalling it — gutters or a satellite dish, for example."},{"@type":"DefinedTerm","name":"Drip Edge","description":"Metal flashing along roof eaves and rakes that directs water away from the fascia and into the gutter."},{"@type":"DefinedTerm","name":"Examination Under Oath (EUO)","description":"A recorded, sworn interview an insurer may request under many policies before it settles a claim."},{"@type":"DefinedTerm","name":"FAIR Plan","description":"The New Hampshire FAIR Plan, the state’s residual-market property insurer for owners who can’t get standard coverage."},{"@type":"DefinedTerm","name":"Holdback","description":"Recoverable depreciation the insurer withholds until repairs or replacement are completed."},{"@type":"DefinedTerm","name":"Ice and Water Shield","description":"A self-adhering waterproof membrane laid under shingles at eaves and valleys to resist ice-dam backup."},{"@type":"DefinedTerm","name":"Ice Dam","description":"A ridge of ice at the roof edge that traps meltwater behind it, which can then back up under shingles and into the house."},{"@type":"DefinedTerm","name":"Line Item","description":"One entry in an estimate, with a description, quantity, unit and price for a single task or material."},{"@type":"DefinedTerm","name":"Matching","description":"Whether repaired or replaced materials reasonably match undamaged areas in color, texture and appearance."},{"@type":"DefinedTerm","name":"Microburst","description":"A sudden, concentrated downdraft from a thunderstorm that can flatten trees and damage roofs along a narrow path."},{"@type":"DefinedTerm","name":"Mitigation","description":"Reasonable steps to prevent further damage after a loss, such as tarping, shutting off water or drying out a basement."},{"@type":"DefinedTerm","name":"New Hampshire Insurance Department","description":"The state regulator in Concord, led by the Insurance Commissioner, which accepts consumer complaints and inquiries about insurers."},{"@type":"DefinedTerm","name":"Nor’easter","description":"A coastal storm with strong northeast winds that can bring heavy snow, rain, coastal flooding and widespread tree damage."},{"@type":"DefinedTerm","name":"Ordinance or Law Coverage","description":"Coverage for added costs of meeting current building codes when damaged property is repaired or rebuilt, often with its own limit."},{"@type":"DefinedTerm","name":"Overhead and Profit (O&P)","description":"A general contractor’s charge for coordinating a job, commonly applied when several trades are involved."},{"@type":"DefinedTerm","name":"Pitch","description":"The steepness of a roof, written as inches of rise per 12 inches of run, such as 8/12."},{"@type":"DefinedTerm","name":"Proof of Loss","description":"A sworn statement of the amount you are claiming, which many policies require within a set time after the insurer asks."},{"@type":"DefinedTerm","name":"Recoverable Depreciation","description":"Depreciation the insurer pays once repairs or replacement are completed within the time the policy allows."},{"@type":"DefinedTerm","name":"Replacement Cost Value (RCV)","description":"The cost to repair or replace damaged property with materials of like kind and quality, before any depreciation."},{"@type":"DefinedTerm","name":"RSA Chapter 417","description":"The New Hampshire law on unfair insurance trade practices, which includes a list of unfair claim settlement practices."},{"@type":"DefinedTerm","name":"Scope of Loss","description":"The full list of damaged items and the repairs each needs. Many appraisal disputes are really scope disputes."},{"@type":"DefinedTerm","name":"Snow Load","description":"The weight of snow and ice on a roof, which can strain or collapse framing when it builds up over a long winter."},{"@type":"DefinedTerm","name":"Square (Roofing)","description":"A unit of 100 square feet of roof surface, used to measure and price roofing."},{"@type":"DefinedTerm","name":"Steep Charge","description":"Extra labor cost for working on roofs above a certain pitch, often starting around 7/12 or 8/12."},{"@type":"DefinedTerm","name":"Sublimit","description":"A lower limit inside a coverage for a particular kind of loss or property, such as mold or debris removal."},{"@type":"DefinedTerm","name":"Suit Limitation","description":"A policy clause setting a window to sue the insurer. Enforceability can depend on New Hampshire law, so check the policy and ask an attorney."},{"@type":"DefinedTerm","name":"Supplement","description":"A request to add items or costs to an existing claim estimate, often after hidden damage is found during repairs."},{"@type":"DefinedTerm","name":"Umpire","description":"The neutral third member of an appraisal panel, who decides only the items the two appraisers can’t settle."},{"@type":"DefinedTerm","name":"Underlayment","description":"The protective layer between roof decking and shingles that serves as a second barrier against water."},{"@type":"DefinedTerm","name":"Vacancy Clause","description":"Policy wording that limits or removes coverage for some perils after a building has been vacant or unoccupied for a set period."},{"@type":"DefinedTerm","name":"Valley (Roofing)","description":"The internal angle where two roof slopes meet, a spot where water concentrates and ice tends to build."},{"@type":"DefinedTerm","name":"Waste Factor","description":"An allowance added to measured roofing or flooring quantities to cover cutting, starter rows and trim pieces."},{"@type":"DefinedTerm","name":"Xactimate","description":"Estimating software widely used by insurers and contractors to price property claims line by line."}],"@id":"https://newhampshireinsuranceappraiser.com/nh-claim-glossary/#definedtermset"}]}</script>
</head>
